param(
  [ValidateSet('x86', 'x64')][string]$CompileArchitecture,
  [string]$Source,
  [string]$Output,
  [ValidatePattern('^\d+\.\d+(\.\d+)?$')][string]$VcVarsVer = '14.29'
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
if (!$Source) { $Source = Join-Path $repoRoot '.deps/dxvk-remix' }
$Source = (Resolve-Path -LiteralPath $Source).Path
if (!$Output) { $Output = Join-Path $repoRoot '.deps/overlay-presenter-test' }
$testDir = [IO.Path]::GetFullPath($Output)
New-Item -ItemType Directory -Force $testDir | Out-Null
function Get-PresenterFileHash([string]$Path) {
  $hasher = [Security.Cryptography.SHA256]::Create()
  try { return [BitConverter]::ToString($hasher.ComputeHash([IO.File]::ReadAllBytes($Path))).Replace('-', '').ToLowerInvariant() }
  finally { $hasher.Dispose() }
}
if ($CompileArchitecture) {
  $vswhere = "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe"
  if (!(Test-Path -LiteralPath $vswhere)) { throw 'Visual Studio installer locator not found' }
  $installation = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
  if ($LASTEXITCODE -ne 0 -or !$installation) { throw 'MSVC build tools not found' }
  $vcvars = Join-Path $installation 'VC/Auxiliary/Build/vcvarsall.bat'
  & cmd.exe /d /s /c "`"$vcvars`" $CompileArchitecture -vcvars_ver=$VcVarsVer >nul && set" | ForEach-Object {
    if ($_ -match '^([^=]+)=(.*)$') { Set-Item -Force -Path "env:$($Matches[1])" -Value $Matches[2] }
  }
  if ($LASTEXITCODE -ne 0 -or !$env:VCToolsVersion -or !$env:VCToolsVersion.StartsWith($VcVarsVer)) {
    throw "MSVC $VcVarsVer environment initialization failed or selected toolset differs"
  }
  . (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
  $compiler = (Get-Command cl.exe -ErrorAction Stop).Source
  Write-Host "Compile actual Presenter source: $Source, architecture: $CompileArchitecture, MSVC: $env:VCToolsVersion"
  Push-Location $testDir
  try {
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /LD "/I$source/bridge/src/util" "$repoRoot/tests/overlay_fake_reshade.cpp" "/Fe:fake-$CompileArchitecture.dll" /link "/DEF:$repoRoot/tests/overlay_fake_reshade.def"
    if ($LASTEXITCODE -ne 0) { throw "ReShade ABI test double compilation failed for $CompileArchitecture" }
    Assert-NativeArchitecture -Path (Join-Path $testDir "fake-$CompileArchitecture.dll") -Architecture $CompileArchitecture
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "/I$source/bridge/src/util" "$repoRoot/tests/overlay_presenter.cpp" user32.lib ole32.lib "/Fe:overlay-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw "Overlay presenter compilation failed for $CompileArchitecture" }
    Assert-NativeArchitecture -Path (Join-Path $testDir "overlay-$CompileArchitecture.exe") -Architecture $CompileArchitecture
    $inputs = @(
      $PSCommandPath, "$repoRoot/tests/overlay_presenter.cpp", "$repoRoot/tests/overlay_fake_reshade.cpp",
      "$repoRoot/tests/overlay_fake_reshade.def", "$Source/bridge/src/server/overlay_presenter.h",
      "$Source/bridge/src/server/steam_ime_native.h", "$Source/bridge/src/util/overlay_input_diagnostics.h",
      "$Source/bridge/src/util/steam_activity_diagnostics.h"
    )
    $sourceHashes = @{}
    foreach ($file in $inputs) { $sourceHashes[$file] = Get-PresenterFileHash $file }
    [pscustomobject]@{
      architecture=$CompileArchitecture; compiler=$compiler
      compiler_version=(Get-Item -LiteralPath $compiler).VersionInfo.FileVersion
      vc_tools_version=$env:VCToolsVersion; windows_sdk_version=$env:WindowsSDKVersion
      source=$Source; source_sha256=$sourceHashes
      executable_sha256=Get-PresenterFileHash (Join-Path $testDir "overlay-$CompileArchitecture.exe")
      fake_dll_sha256=Get-PresenterFileHash (Join-Path $testDir "fake-$CompileArchitecture.dll")
    } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $testDir "provenance-$CompileArchitecture.json") -Encoding UTF8
  } finally { Pop-Location }
} else {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $PSCommandPath -CompileArchitecture $arch -Source $Source -Output $testDir -VcVarsVer $VcVarsVer
    if ($LASTEXITCODE -ne 0) { throw "Overlay presenter compilation failed for $arch" }
  }
  & (Join-Path $testDir 'overlay-x86.exe') (Join-Path $testDir 'overlay-x64.exe')
  if ($LASTEXITCODE -ne 0) { throw 'x86 parent / x64 presenter failed' }
  & (Join-Path $testDir 'overlay-x64.exe') (Join-Path $testDir 'overlay-x86.exe')
  if ($LASTEXITCODE -ne 0) { throw 'x64 parent / x86 presenter failed' }
}
